import torch.nn as nn
import torch.nn.functional as F
import math

os.environ["CXX"] = "hipcc"

batch_size = 128
max_seqlen = 1024
seq_len = 512
n_embd = 768
n_head = 8
attn_pdrop = 0.0
resid_pdrop = 0.0

causal_att_cpp = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <cmath>

__global__ void causal_attention_kernel(const float* q, const float* k, const float* v, float* y,
                                        int B, int nh, int T, int hs, float scale) {
    unsigned int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= static_cast<unsigned int>(B * nh * T)) return;

    unsigned int b = idx / (nh * T);
    unsigned int h_offset = idx % (nh * T);
    unsigned int h = h_offset / T;
    unsigned int i = h_offset % T;

    size_t off_bh = static_cast<size_t>(b * nh + h) * T * hs;
    size_t qoff = off_bh + static_cast<size_t>(i) * hs;

    // First pass: compute softmax stats (max m, sum_exp s)
    float m = -INFINITY;
    float s = 0.0f;
    for (int j = 0; j <= static_cast<int>(i); ++j) {
        size_t koff = off_bh + static_cast<size_t>(j) * hs;
        float dot = 0.0f;
        for (int d = 0; d < hs; ++d) {
            dot += q[qoff + d] * k[koff + d];
        }
        dot *= scale;

        float m_new = fmaxf(m, dot);
        s *= expf(m - m_new);
        s += expf(dot - m_new);
        m = m_new;
    }

    // Second pass: compute output
    for (int d = 0; d < hs; ++d) {
        float sum_d = 0.0f;
        for (int j = 0; j <= static_cast<int>(i); ++j) {
            size_t koff = off_bh + static_cast<size_t>(j) * hs;
            float dot = 0.0f;
            for (int dd = 0; dd < hs; ++dd) {
                dot += q[qoff + dd] * k[koff + dd];
            }
            dot *= scale;
            float w = expf(dot - m) / s;
            sum_d += w * v[koff + d];
        }
        y[qoff + d] = sum_d;
    }
}

torch::Tensor causal_attention_hip(torch::Tensor q, torch::Tensor k, torch::Tensor v) {
    auto B = q.size(0);
    auto nh = q.size(1);
    auto T = q.size(2);
    auto hs = q.size(3);
    auto opts = q.options();
    auto y = torch::empty({B, nh, T, hs}, opts);

    int64_t B_i = B.item<int64_t>();
    int64_t nh_i = nh.item<int64_t>();
    int64_t T_i = T.item<int64_t>();
    int64_t hs_i = hs.item<int64_t>();
    float scale = 1.0f / sqrtf(static_cast<float>(hs_i));

    const int block_size = 256;
    const int64_t total = B_i * nh_i * T_i;
    const int num_blocks = (total + block_size - 1) / block_size;

    dim3 grid(num_blocks);
    dim3 blk(block_size);

    hipLaunchKernelGGL(causal_attention_kernel, grid, blk, 0, nullptr,
                       q.data_ptr<float>(), k.data_ptr<float>(), v.data_ptr<float>(),
                       y.data_ptr<float>(),
                       static_cast<int>(B_i), static_cast<int>(nh_i), static_cast<int>(T_i), static_cast<int>(hs_i),
                       scale);
    return y;
}
"""

